NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'Philippians'

CHAPTERS = {
    1: {
        1: 'Paulus und Timotheus, Knechte von Christus Jesus. /An alle Heiligen in Christus Jesus, die in Philippi sind, samt Aufsehern und Dienern: /',
        2: 'Gnade [sei mit] euch und Frieden von Gott, unserem Vater, und dem Herrn Jesus Christus!',
        3: 'Ich danke meinem Gott bei aller Erinnerung an euch –',
        4: 'allezeit in all meiner Fürbitte für euch alle, wobei ich die Fürbitte mit Freude verrichte –',
        5: 'wegen eurer Teilhabe an der guten Nachricht vom ersten Tag an bis jetzt,',
        6: 'denn ich bin genau davon überzeugt, dass derjenige, der unter euch ein gutes Werk begonnen hat, es bis zum Tag Christi Jesu vollenden wird.',
        7: 'Schließlich ‹steht es mir zu›, dies über euch alle zu denken, weil ich euch im Herzen habe, da ihr alle mit mir Teilhaber an der Gnade seid, sowohl an meiner Gefangenschaft als auch an der Verteidigung und Bestätigung der guten Nachricht.',
        8: 'Denn Gott [ist] mein Zeuge, wie ich mich nach euch allen sehne mit der Zuneigung von Christus Jesus.',
        9: 'Und Folgendes bete ich: dass eure Liebe noch mehr und mehr wachse in Erkenntnis und allem Urteilsvermögen,',
        10: 'damit ihr die entscheidenden [Dinge] befürwortet, sodass ihr unverfälscht und makellos seid zum Tag des Christus,',
        11: 'erfüllt mit der Frucht der Gerechtigkeit, die durch Jesus Christus [entsteht], zur Ehre und zum Lob Gottes.',
        12: 'Nun will ich euch wissen lassen, Geschwister, dass ‹meine Umstände› erst recht zur Förderung der guten Nachricht geführt haben,',
        13: 'sodass meine Gefangenschaft in Christus im gesamten Prätorium und all den übrigen [Soldaten] bekannt geworden ist',
        14: 'und die meisten der Geschwister – da sie auf den Herrn vertrauen – es wegen meiner Gefangenschaft häufiger wagen, das Wort furchtlos zu sagen.',
        15: 'Zwar predigen einige Christus sogar aus Neid und Rivalität, aber einige auch aus gutem Willen:',
        16: 'Die einen [tun es] aus Liebe, weil sie wissen, dass ich zur Verteidigung der guten Nachricht bestimmt bin;',
        17: 'die anderen verkünden Christus aus Selbstsucht, nicht ohne Hintergedanken, weil sie meinen, [dadurch] Ärger zu verursachen für meine Gefangenschaft.',
        18: 'Was [folgt] denn? Lediglich, dass auf jede Weise – ob als Vorwand oder Wahrheit – Christus verkündet wird, und darüber freue ich mich. Doch ich werde mich auch [weiterhin] freuen,',
        19: 'denn ich weiß, dass mir dies zu [meiner] Rettung ausgehen wird durch eure Fürbitte und die Unterstützung des Geistes von Jesus Christus,',
        20: 'entsprechend meiner großen Erwartung und Hoffnung, dass ich in nichts beschämt sein werde, sondern Christus (wie immer, so auch jetzt) in aller Offenheit gepriesen wird durch meinen Körper, ob durch Leben oder durch Tod.',
        21: 'Denn für mich [ist] das Leben Christus und das Sterben ein Gewinn.',
        22: 'Aber wenn das Leben im Fleisch [vorgeht], dann [ist] dies für mich fruchtbare Arbeit – und was ich vorziehen soll, weiß ich nicht.',
        23: 'Ich werde aber von beidem bedrängt, da ich den Wunsch habe, zu sterben und mit Christus zu sein, denn [das wäre] sehr viel besser.',
        24: 'Der Verbleib im Fleisch aber [ist] euretwegen nötiger.',
        25: 'Und weil ich davon überzeugt bin, weiß ich, dass ich bleiben und mit euch allen weitermachen werde zu eurer Förderung und zur Freude des Glaubens,',
        26: 'damit euer Rühmen in Christus Jesus durch mich vermehrt wird, durch meine Rückkehr zu euch.',
        27: 'Lebt nur würdig der guten Nachricht von Christus, damit ich – [unabhängig davon], ob ich komme und euch sehe oder ob ich abwesend bin – ‹über euch› höre, dass ihr fest steht in dem einen Geist, indem ihr geschlossen Seite an Seite für den Glauben der guten Nachricht kämpft',
        28: 'und euch durch nichts von den Widersachern einschüchtern lasst (was für sie ein Hinweis des Verderbens ist, aber eurer Rettung, und das von Gott!).',
        29: 'Denn euch wurde das „um Christi willen“geschenkt, nicht nur das „an ihn Glauben“, sondern auch das „um seinetwillen Leiden“,',
        30: 'weil ihr denselben Kampf führt, den ihr an mir gesehen habt und jetzt über mich hört.',
    },
    2: {
        1: 'Wenn nun irgendeine Ermutigung in Christus, wenn irgendein Trost der Liebe, wenn irgendeine Gemeinschaft des Geistes, wenn irgendein Mitgefühl und Mitleid [vorhanden ist],',
        2: 'dann erfüllt meine Freude dadurch, dass ihr dasselbe denkt und dieselbe Liebe habt; gleichgesinnt und auf das Eine bedacht seid;',
        3: 'nichts aus Selbstsucht oder aus Eitelkeit [tut], sondern in Demut einander für bedeutender haltet als euch selbst;',
        4: 'jeder nicht die eigenen [Interessen] berücksichtigt, sondern jeder gerade die der anderen.',
        5: 'Seid unter euch darauf bedacht, was auch in Christus Jesus [war],',
        6: 'welcher, obwohl er in der Gestalt Gottes existierte, / es nicht als sein gutes Recht betrachtete, /Gott gleich zu sein, /',
        7: 'sondern sich selbst entäußerte, / indem er die Gestalt eines Knechtes annahm, / indem er ‹den Menschen ähnlich› wurde / und im Aussehen als Mensch erschien; /',
        8: 'er machte sich selbst gering, / indem er bis hin zum Tod gehorsam war, / und zwar zum Tod an einem Kreuz. /',
        9: 'Darum hat Gott ihn ja erhöht / und ihm den Namen verliehen, / der über jedem Namen [ist], /',
        10: 'damit im Namen von Jesus / sich jedes Knie beuge, / von himmlischen und irdischen und unterirdischen [Wesen], /',
        11: 'und jede Zunge bekenne, / dass Jesus Christus Herr [ist], / zur Ehre Gottes des Vaters.',
        12: 'Darum, meine geliebten [Geschwister]: Genauso wie ihr stets gehorsam gewesen seid – nicht nur während meiner Anwesenheit, sondern jetzt umso mehr während meiner Abwesenheit –, wirkt auf eure eigene Rettung hin mit Ehrfurcht und Zittern!',
        13: 'Denn Gott ist es, der in euch sowohl das Wollen als auch das Wirken bewirkt zu [seinem] Wohlgefallen.',
        14: 'Tut alles ohne Gemurre und Zweifel,',
        15: 'damit ihr tadellos und unverdorben seid, makellose Kinder Gottes inmitten einer gemeinen und verkehrten Generation, unter der ihr scheint wie Sterne im Universum,',
        16: 'indem ihr das Wort des Lebens festhaltet, mir zum Rühmen am Tag Christi, dass ich weder vergeblich gelaufen bin, noch mich vergeblich abgemüht habe.',
        17: 'Doch auch wenn ich als Trankopfer auf das Opfer und den Dienst eures Glaubens gegossen werde, freue ich mich und freue ich mich zusammen mit euch allen.',
        18: 'Darüber aber sollt auch ihr euch freuen und zusammen mit mir froh sein.',
        19: 'Ich hoffe aber im Herrn Jesus, Timotheus bald zu euch zu schicken, damit auch ich ermutigt werde, sobald ich ‹eure Umstände› erfahren habe.',
        20: 'Ich habe nämlich niemanden [ihm] Gleichgesinntes, der sich ernsthaft ‹um eure Belange› kümmern wird;',
        21: 'denn sie alle suchen ihre eigenen Interessen, nicht die von Jesus Christus.',
        22: 'Aber ihr kennt seine Zuverlässigkeit, dass er – wie ein Kind dem Vater – mit mir für die gute Nachricht gedient hat.',
        23: 'Ich hoffe deshalb, ihn umgehend zu schicken, sobald ich meine Belange überblicke;',
        24: 'ich vertraue aber im Herrn, dass auch ich selbst bald kommen werde.',
        25: 'Ich habe es aber für notwendig gehalten, Epaphroditus, meinen Bruder und Mitarbeiter und Mitstreiter und euren Abgesandten und Gehilfen in meiner Notlage, zu euch zu schicken,',
        26: 'weil er sich nach euch allen sehnte und besorgt war, weil ihr gehört hattet, dass er krank war.',
        27: 'Denn er war zwar krank, dem Tode nah; doch Gott hat ihn verschont; und nicht nur ihn, sondern auch mich, damit ich nicht Kummer über Kummer habe.',
        28: 'Darum habe ich ihn umso eiliger geschickt, damit ihr euch freut, wenn ihr ihn wiederseht, und ich unbesorgter bin.',
        29: 'Heißt ihn also willkommen im Herrn mit aller Freude und haltet solche [Leute] in Ehren,',
        30: 'weil er um des Werkes Christi willen dem Tod nahekam und [sein] Leben riskierte, um die Lücke auszufüllen, die ihr hinterlassen habt, im Dienst für mich.',
    },
    3: {
        1: 'Im Übrigen, meine Geschwister: Freut euch im Herrn! Euch dasselbe zu schreiben, [ist] mir nicht lästig, aber euch [macht es] standfest.',
        2: 'Achtet auf die Hunde, achtet auf die schlechten Arbeiter, achtet auf die Zerschneidung!',
        3: 'Die Beschneidung sind nämlich wir, die wir durch den Geist Gottes dienen und uns in Christus Jesus rühmen und nicht aufs Fleisch vertrauen,',
        4: 'obwohl ich ebenfalls aufs Fleisch Vertrauen haben [könnte]. Wenn jemand anderes meint, aufs Fleisch vertrauen [zu können], dann ich erst recht:',
        5: 'Beschneidung am achten Tag, aus dem Volk Israel, dem Stamm Benjamins, ein Hebräer von Hebräern, dem Gesetz nach ein Pharisäer,',
        6: 'dem Eifer nach ein Verfolger der Gemeinde, der Gerechtigkeit im Gesetz nach tadellos gewesen.',
        7: 'Doch was mir Gewinn war, das habe ich wegen Christus als Verlust erachtet.',
        8: '‹Mehr noch›: Ich meine sogar, dass alles ein Verlust ist wegen der Überlegenheit der Erkenntnis von Christus Jesus, meinem Herrn, um dessen willen ich alles eingebüßt habe, und ich erachte es als Dreck, damit ich Christus gewinne',
        9: 'und in ihm gefunden werde, weil ich nicht meine eigene Gerechtigkeit habe, die aus dem Gesetz [entsteht], sondern die durch Glauben an Christus [entsteht], die Gerechtigkeit aus Gott aufgrund des Glaubens,',
        10: 'um ihn und die Kraft seiner Auferstehung und die Gemeinschaft seiner Leiden zu kennen, sodass ich seinem Tod gleichgestaltet werde,',
        11: 'wenn ich irgendwie zur Auferstehung von den Toten gelange.',
        12: 'Nicht, dass ich es schon erlangt habe oder schon vollkommen geworden bin; ich strebe aber danach [zu sehen], ob ich auch ergreife, wozu ich auch von Christus Jesus ergriffen worden bin.',
        13: 'Geschwister, ich schätze mich selbst nicht so ein, es ergriffen zu haben. Eines aber [steht fest]: Indem ich einerseits das Zurückliegende vergesse, mich andererseits dem Vorausliegenden entgegenstrecke,',
        14: 'jage ich dem Ziel entgegen, zu dem Siegespreis hin der nach oben gerichteten Berufung Gottes in Christus Jesus.',
        15: 'So viele also vollkommen [sind], lasst uns darauf bedacht sein (und wenn ihr anderweitig auf etwas bedacht seid, dann wird Gott euch auch das offenbaren):',
        16: 'nur an demselben festzuhalten, was wir erlangt haben.',
        17: 'Werdet meine Mitnachahmer, Geschwister, und beobachtet diejenigen, die so leben, wie ihr uns als Vorbild habt.',
        18: 'Denn viele, über die ich häufig zu euch sprach, jetzt aber sogar unter Tränen spreche, leben als die Feinde des Kreuzes Christi,',
        19: 'deren Ende das Verderben, deren Gott der Bauch und die Ehre in ihrer Schande [ist], da sie [nur] an das Irdische denken.',
        20: 'Unser Bürgerrecht besteht nämlich in den Himmeln, von wo wir auch einen Retter erwarten: den Herrn Jesus Christus,',
        21: 'der den Körper unserer Niedrigkeit ähnlich dem Körper seiner Herrlichkeit umgestalten wird, gemäß der Kraft, mit der er sich auch alles unterordnen kann.',
    },
    4: {
        1: 'Darum, meine geliebten und sehnsüchtig vermissten Geschwister, meine Freude und Krone: In dieser Weise steht fest im Herrn, ihr Geliebten.',
        2: 'Euodia ermahne ich und Syntyche ermahne ich, dasselbe zu denken im Herrn.',
        3: 'Ja, ich bitte auch dich, wahrer Syzygos, hilf ihnen, die mir in der guten Nachricht zur Seite gestanden sind, zusammen mit Klemens und den übrigen meiner Mitarbeiter, deren Namen im Buch des Lebens [stehen].',
        4: 'Freut euch stets im Herrn! Wieder werde ich es sagen: Freut euch!',
        5: 'Eure Mildtätigkeit soll allen Menschen bekannt werden. Der Herr [ist] nahe.',
        6: 'Sorgt euch um nichts, sondern macht in jeder [Lage] durch Gebet und Flehen mit Dank eure Anliegen vor Gott bekannt!',
        7: 'Dann wird der Friede Gottes, der alle Vernunft übertrifft, eure Herzen und eure Gedanken behüten in Christus Jesus.',
        8: 'Im Übrigen, Geschwister: Alles, was wahrhaftig, was ehrbar, was gerecht, was unschuldig, was freundlich, was empfehlenswert ist, sei es irgendeine Tugend und sei es irgendein Lob – das bedenkt!',
        9: 'Was ihr auch gelernt und übernommen und gehört und gesehen habt durch mich, das tut! Dann wird der Gott des Friedens mit euch sein.',
        10: 'Ich habe mich aber im Herrn sehr gefreut, dass ihr jetzt endlich das Bedachtsein für mich erneuert habt, worauf ihr auch bedacht wart, aber keine Gelegenheit hattet, [entsprechend zu handeln].',
        11: 'Nicht, dass ich wegen Mangel spreche; denn ich habe gelernt, [mit den Umständen] zufrieden zu sein, in denen ich mich befinde.',
        12: 'Ich verstehe es, auch mit wenig auszukommen; ich verstehe es, auch reich zu sein. In jeder [Lage] und in allen [Umständen] habe ich das Geheimnis gelernt, sowohl satt zu sein als auch Hunger zu haben, sowohl reich zu sein als auch Mangel zu leiden.',
        13: 'Ich vermag alles durch den, der mich befähigt.',
        14: 'Trotzdem habt ihr gut gehandelt, indem ihr Anteil nahmt an meiner Bedrängnis.',
        15: 'Auch ihr Philipper wisst aber, dass zu Beginn der guten Nachricht, als ich von Makedonia losging, keine Gemeinde mich teilhaben ließ in der Frage des Gebens und Nehmens, außer ihr allein,',
        16: 'denn auch in Thessalonich habt ihr mir ‹ein ums andere Mal› etwas für den Bedarf geschickt.',
        17: 'Nicht, dass ich das Geschenk suche, sondern ich suche die Frucht, die zu euren Gunsten anwächst.',
        18: 'Ich habe aber alles erhalten und bin reich; ich bin ausgefüllt, denn ich habe von Epaphroditus die [Gaben] von euch empfangen, ein Duft von Wohlgeruch, ein willkommenes Opfer, das Gott gefällt.',
        19: 'Mein Gott aber wird all euren Bedarf entsprechend seinem Reichtum ausfüllen durch die Herrlichkeit in Christus Jesus.',
        20: 'Unserem Gott und Vater aber [gebührt] die Ehre ‹für immer und ewig›! Amen.',
        21: 'Grüßt jeden Heiligen in Christus Jesus. Es grüßen euch die Geschwister bei mir.',
        22: 'Es grüßen euch alle Heiligen, besonders aber die vom Haushalt des Kaisers.',
        23: 'Die Gnade des Herrn Jesus Christus [sei] mit eurem Geist!',
    },
}
